import { vi } from 'vitest';
import { expect, it } from 'vitest';
import { andThen, combineAll, err, fromPromise, map, ok, unwrapOr } from './Solution';
import { matchResult } from './Solution';

it('空与零值成功分支仍算成功', () => {
  expect(unwrapOr(ok(0), -1)).toBe(0);
  expect(unwrapOr(ok(''), 'fallback')).toBe('');
  expect(unwrapOr(ok(null), 'fallback')).toBe(null);
  expect(unwrapOr(err('nope'), 'fallback')).toBe('fallback');
  expect(map(ok(0), (n) => n + 1)).toEqual({ ok: true, value: 1 });
});

it('combineAll 空数组返回 ok 空数组', () => {
  const res = combineAll([]);
  expect(res.ok).toBe(true);
  expect(res.ok ? res.value.length : -1).toBe(0);
  expect(combineAll([ok(1), ok(2)]).ok).toBe(true);
});

it('combineAll 短路且不再读后续元素', () => {
  const probes: number[] = [];
  const lazy = {
    get ok() {
      probes.push(1);
      return false;
    },
    get error() {
      probes.push(2);
      return 'never';
    },
  };
  const list = [ok(1), err('first'), lazy, err('third')];
  const res = combineAll(list);
  expect(res.ok).toBe(false);
  expect(!res.ok ? res.error : null).toBe('first');
  expect(probes).toEqual([]);
});

it('超大列表 combineAll 保序且引用不变', () => {
  const items = Array.from({ length: 1000 }, (_unused, i) => ok({ id: i }));
  const res = combineAll(items);
  expect(res.ok).toBe(true);
  if (res.ok) {
    expect(res.value.length).toBe(1000);
    expect(res.value[999]).toBe(items[999].ok ? items[999].value : null);
  }
  const withErr = items.slice(0, 999).concat([err('tail')]);
  const res2 = combineAll(withErr);
  expect(!res2.ok ? res2.error : null).toBe('tail');
});

it('失败原因原样透传且 andThen 对 Err 直通', () => {
  const marker = { code: 'RATE_LIMITED', retryable: true };
  const res = andThen(err(marker), vi.fn(() => ok(1)));
  expect(res.ok).toBe(false);
  expect(!res.ok ? res.error : null).toBe(marker);
  expect(andThen(ok(2), (n) => ok(n * 10))).toEqual({ ok: true, value: 20 });
  expect(andThen(ok(2), () => err('stop')).ok).toBe(false);
});

it('reject undefined 时归一化且不含 undefined 文案', async () => {
  const res = await fromPromise(Promise.reject(undefined));
  expect(res.ok).toBe(false);
  if (!res.ok) {
    expect(res.error.kind).toBe('unknown');
    expect(res.error.message).toBe('unknown rejection');
    expect(res.error.raw).toBe(undefined);
  }
  const res2 = await fromPromise(Promise.reject('boom-string'));
  if (!res2.ok) {
    expect(res2.error.kind).toBe('value');
    expect(res2.error.message).toBe('boom-string');
  }
  const res3 = await fromPromise(Promise.reject(new Error('real one')));
  if (!res3.ok) {
    expect(res3.error.kind).toBe('error');
    expect(res3.error.message).toBe('real one');
  }
  const res4 = await fromPromise(Promise.resolve(42));
  expect(res4.ok ? res4.value : null).toBe(42);
});

it('matchResult 按判别式穷尽两个分支', () => {
  const arms = { ok: (v: number) => 'ok:' + v, err: (e: string) => 'err:' + e };
  expect(matchResult(ok(7), arms)).toBe('ok:7');
  expect(matchResult(err('bad'), arms)).toBe('err:bad');
  expect(
    matchResult({ ok: 'not-a-boolean' } as never, arms),
  ).toBe('unreachable');
});

