/**
 * Result 建模：ok 字段是唯一判别式（不是"有没有 value"），
 * 所以 ok(null) / ok(0) / ok('') 都是成功分支。
 */
export interface Ok<T> {
  readonly ok: true;
  readonly value: T;
}

export interface Err<E> {
  readonly ok: false;
  readonly error: E;
}

export type Result<T, E> = Ok<T> | Err<E>;

export interface NormalizedError {
  readonly kind: 'error' | 'value' | 'unknown';
  readonly message: string;
  readonly raw: unknown;
}

export const ok = <T,>(value: T): Ok<T> => ({ ok: true, value });

export const err = <E,>(error: E): Err<E> => ({ ok: false, error });

export function unwrapOr<T, E>(res: Result<T, E>, fallback: T): T {
  return res.ok ? res.value : fallback;
}

export function map<T, U, E>(res: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  return res.ok ? ok(fn(res.value)) : res;
}

export function andThen<T, U, E>(res: Result<T, E>, fn: (value: T) => Result<U, E>): Result<U, E> {
  return res.ok ? fn(res.value) : res;
}

/** 顺序短路：遇到第一个 Err 立刻返回，绝不读后续元素（getter 探针会抓到越界访问）。 */
export function combineAll<T, E>(list: readonly Result<T, E>[]): Result<T[], E> {
  const values: T[] = [];
  for (const item of list) {
    if (!item.ok) return item;
    values.push(item.value);
  }
  return ok(values);
}

/** catch 到的永远是 unknown：不许当 Error 用，也不许把 undefined 写成 message。 */
export function normalizeError(raw: unknown): NormalizedError {
  if (raw instanceof Error) return { kind: 'error', message: raw.message || raw.name, raw };
  if (raw === undefined || raw === null) return { kind: 'unknown', message: 'unknown rejection', raw };
  if (typeof raw === 'string') return { kind: 'value', message: raw, raw };
  const maybe = raw as { message?: unknown };
  if (typeof maybe.message === 'string') return { kind: 'value', message: maybe.message, raw };
  return { kind: 'value', message: String(raw), raw };
}

export function fromPromise<T>(promise: Promise<T>): Promise<Result<T, NormalizedError>> {
  return promise.then(
    (value) => ok(value),
    (reason: unknown) => err(normalizeError(reason)),
  );
}

type Arms<T, E, R> = { ok: (value: T) => R; err: (error: E) => R };

/** 穷尽：两个分支都必须给；判别式不是 boolean 时走 unreachable（配 satisfies never 在类型层兜底）。 */
export function matchResult<T, E, R>(res: Result<T, E>, arms: Arms<T, E, R>): R {
  const flag = (res as { ok?: unknown }).ok;
  if (flag === true) return arms.ok((res as Ok<T>).value);
  if (flag === false) return arms.err((res as Err<E>).error);
  const exhausted: never = flag as never;
  void exhausted;
  return 'unreachable' as unknown as R;
}

