export const ok = (value) => ({ ok: true, value });
export const err = (error) => ({ ok: false, error });

export function unwrapOr(res, fallback) {
  // 用真值判断代替判别式：ok(0) / ok('') / ok(null) 全被误判为失败
  return res.value ? res.value : fallback;
}

export function map(res, fn) {
  return res.value ? ok(fn(res.value)) : res;
}

export function andThen(res, fn) {
  return res.value ? fn(res.value) : res;
}

export function combineAll(list) {
  const values = [];
  let firstError = null;
  for (const item of list) {
    if (item.value === undefined) {
      if (!firstError) firstError = err(item.error);
    } else {
      values.push(item.value);
    }
  }
  return firstError ?? ok(values);
}

export function fromPromise(promise) {
  return promise.then((value) => ok(value), (reason) => err({ kind: 'error', message: reason.message, raw: reason }));
}

export function matchResult(res, arms) {
  return res.value !== undefined ? arms.ok(res.value) : arms.err(res.error);
}
